def _level(label, icon, blurb, catalog):
    return {"label":label,"icon":icon,"blurb":blurb,"topics":[{**t,"games":list(catalog.get(t["label"],[]))} for t in _TOPICS]}
MENU = [
 {"label":"Games","icon":"🎮","kind":"game","blurb":"Play, test, and discover!","levels":[
  _level("Beginner","🌱","One clear idea at a time.",_BEGINNER_GAMES),
  _level("Intermediate","🔎","Picture first, then a science word.",_INTERMEDIATE_GAMES),
  _level("Advanced","🚀","Follow a longer cause-and-effect chain.",_ADVANCED_GAMES)]},
 {"label":"Lessons","icon":"📚","kind":"lesson","blurb":"Look, name, then play.","levels":[
  _level("Beginner","🌱","See one clear difference.",lesson_menu_for("Beginner")),
  _level("Intermediate","🔎","Picture first, then a science word.",lesson_menu_for("Intermediate")),
  _level("Advanced","🚀","Follow a longer cause-and-effect chain.",lesson_menu_for("Advanced"))]}
]
def label(x): return f"{x['icon']} {x['label']}"
def load_module(filename):
    path=MODULES_DIR/filename; name="science_playground_"+path.stem
    spec=importlib.util.spec_from_file_location(name,path)
    if spec is None or spec.loader is None: raise ImportError(path)
    module=importlib.util.module_from_spec(spec); sys.modules[name]=module; spec.loader.exec_module(module); return module
def render_home():
    st.header("Welcome, scientist!")
    st.write("Pick Games to play, or Lessons to look, name, and then play.")
    for topic in _TOPICS: st.markdown(f"{topic['icon']} **{topic['label']}** — {topic['blurb']}")
    st.info("Waves 1 and 2 are picture-first: every beginner topic, plus Intermediate Motion.")
def main():
    st.set_page_config(page_title="Science Playground",page_icon="🔬",layout="wide",initial_sidebar_state="expanded")
    st.markdown("""<style>html,body,[class*="css"]{font-size:1.12rem} div.stButton>button{font-size:1.2rem;padding:.65rem 1rem;border-radius:14px} section[data-testid="stSidebar"]{background:linear-gradient(180deg,#e5f8ff,#f0ffe8,#fff5d9)} .hero{font-size:2.5rem;font-weight:850;color:#17324d}</style>""",unsafe_allow_html=True)
    with st.sidebar:
        st.markdown("### 🔬 Science Playground"); st.caption("Big ideas for little explorers")
        mode_text=st.radio("Where do you want to go?",["Home"]+[label(x) for x in MENU])
        mode=level=topic=game=None; games=[]
        if mode_text!="Home":
            mode=next(x for x in MENU if label(x)==mode_text)
            level_text=st.radio("Which level?",[label(x) for x in mode["levels"]],key="level_"+mode["label"])
            level=next(x for x in mode["levels"] if label(x)==level_text)
            topic_text=st.radio("Which topic?",[label(x) for x in level["topics"]],key="topic_"+mode["label"]+"_"+level["label"])
            topic=next(x for x in level["topics"] if label(x)==topic_text); games=topic["games"]
            if games:
                pick="Which lesson?" if mode["kind"]=="lesson" else "Which game?"
                game_text=st.radio(pick,[label(x) for x in games],key="pick_"+mode["label"]+"_"+level["label"]+"_"+topic["label"])
                game=next(x for x in games if label(x)==game_text)
        st.divider(); st.caption("Grown-ups: every choice is deterministic and discussion-friendly.")
    st.markdown('<div class="hero">Science Playground</div>',unsafe_allow_html=True)
    st.caption("Push, shine, build, grow, and discover.")
    if mode_text=="Home": render_home(); return
    if not games:
        st.header(f"{mode['icon']} {mode['label']} · {level['label']} · {topic['label']}")
        st.info("Nothing is listed here yet.")
        return
    if mode["kind"] == "lesson":
        run_lesson(get_lesson(game["id"]))
        return
    module=load_module(game["file"]); getattr(module,game["entry"])()
if __name__=="__main__": main()
